import os, json
models = set()
for judge_dir in os.listdir('judgment_data_n17'):
    path = os.path.join('judgment_data_n17', judge_dir)
    if not os.path.isdir(path): continue
    for f in os.listdir(path):
        if f.endswith('.jsonl'):
            with open(os.path.join(path, f)) as fh:
                for line in fh:
                    try:
                        d = json.loads(line)
                        models.add(d.get('model_a', d.get('model', '')))
                    except: pass
print(f'Total unique target models: {len(models)}')
for m in sorted(models):
    print(f'  {m}')
